# 1. Create a hosted zone (public — accessible from internet)
aws route53 create-hosted-zone \
  --name myapp.com \
  --caller-reference $(date +%s)

# Note the 4 NS records returned — add them to your domain registrar
# (If domain is registered in Route53, this is automatic)

# 2. Create DNS records
# Use change-resource-record-sets for all record operations:
aws route53 change-resource-record-sets \
  --hosted-zone-id Z1234567890 \
  --change-batch '{
    "Changes": [
      {
        "Action": "UPSERT",
        "ResourceRecordSet": {
          "Name": "myapp.com",
          "Type": "A",
          "AliasTarget": {
            "HostedZoneId": "Z2FDTNDATAQYW2",
            "DNSName": "d1234567890.cloudfront.net",
            "EvaluateTargetHealth": false
          }
        }
      },
      {
        "Action": "UPSERT",
        "ResourceRecordSet": {
          "Name": "www.myapp.com",
          "Type": "CNAME",
          "TTL": 300,
          "ResourceRecords": [{"Value": "myapp.com"}]
        }
      }
    ]
  }'
